const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // The Lut Desert, a known hot spot for LST.
  const geometry = ee.Geometry.Point([58.4, 30.5]);
  const startDate = '2018-01-01';
  const endDate = '2018-12-31';

  // 2. Data Acquisition
  const modisLST = ee.ImageCollection('MODIS/11A1.061')
    .filterDate(startDate, endDate)
    .filterBounds(geometry);

  // 3. Data Availability Check (C1)
  const collectionSize = modisLST.size().getInfo();
  if (collectionSize === 0) {
    console.log("Evidence: No MODIS LST images found for the specified date and location.");
    console.log("A");
    return;
  }
  console.log(`Image Collection Size: ${collectionSize}`);

  // 4. Processing & Calculation
  // Select the daytime LST band.
  const lstDay = modisLST.select('LST_Day_1km');

  // Convert from Kelvin (with scale factor) to Celsius.
  const toCelsius = function(image) {
    const celsius = image.multiply(0.02).subtract(273.15);
    return celsius.copyProperties(image, ['system:time_start']);
  };
  const lstCelsius = lstDay.map(toCelsius);

  // Find the maximum temperature over the year.
  const maxTempImage = lstCelsius.max();

  // Reduce the region to get the single max value at the point.
  // Using a reducer with a geometry is more efficient than sampling.
  const stats = maxTempImage.reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: 1000, // Native resolution of MODIS LST is 1km.
    maxPixels: 1e9
  });

  const maxTemp = stats.get('LST_Day_1km_max').getInfo();
  const pixelCount = stats.get('LST_Day_1km_count').getInfo();

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log("Evidence: Although images exist, no valid pixels were found at the location.");
    console.log("C2");
    return;
  }

  if (maxTemp === null || typeof maxTemp === 'undefined') {
    console.log("Evidence: Calculation failed. Could not determine a valid temperature value.");
    console.log("C3");
    return;
  }

  const threshold = 75; // degrees Celsius
  const isAboveThreshold = maxTemp > threshold;

  console.log(`Location: Lut Desert Point (${geometry.coordinates().getInfo().join(', ')})`);
  console.log(`Year: 2018`);
  console.log(`Valid Pixel Count: ${pixelCount}`);
  console.log(`Maximum Land Surface Temperature (LST): ${maxTemp.toFixed(2)} °C`);
  console.log(`Threshold for comparison: ${threshold} °C`);
  console.log(`Was the temperature above the threshold? ${isAboveThreshold ? 'Yes' : 'No'}`);

  if (isAboveThreshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`An error occurred: ${e.message}`);
    console.log("D");
  }
}

initEE();
